/*
 * monster_bios_layout.c
 * -----------------------------------------------------------------------------
 * OTOMATIK URETILDI - monster_bios.bin dosyasindan UEFI yapisina gore.
 *
 * Her satir bir dugumdur. Alanlar:
 *   kind      : image / region / FV / file / section
 *   parent    : ust dugumun indeksi (-1 = kok)
 *   container : bu dugumun offset'i hangi section'in acilmis icerigine gore?
 *               (-1 = dogrudan imaj dosyasi, offset mutlak)
 *   offset    : mutlak imaj ofseti veya container icindeki goreli ofset
 *   size      : boyut (bayt)
 *   type      : FFS/file/section/bolge turu
 *   name      : UI section'indan okunan modul adi veya tur adi
 *   guid      : FFS/FV GUID'i (metin)
 *
 * Toplam dugum sayisi: 2630
 * -----------------------------------------------------------------------------
 */
